css:
[data-bz-node="phs"]{color:#fff}
[data-bz-node="phs-copy"] .bz-eyebrow{color:#fff;font-family:var(--font-heading);font-weight:600;font-size:13px;letter-spacing:.14em;text-transform:uppercase;margin:0 0 16px;border-left:4px solid #C41230;padding-left:12px}
[data-bz-node="phs-title"] h1{font-family:var(--font-heading);font-weight:700;font-size:clamp(40px,6vw,80px);line-height:1;text-transform:uppercase;color:#fff;margin:0 0 24px;letter-spacing:0}
[data-bz-node="phs-lead"] p{font-size:18px;line-height:1.6;color:#fff;margin:0;max-width:560px}
[data-bz-node="phs-ctas"] .bz-btns{display:flex;flex-wrap:wrap;gap:16px;margin:0}
[data-bz-node="phs-ctas"] .bz-btn{font-family:var(--font-heading);font-weight:600;font-size:15px;letter-spacing:.1em;text-transform:uppercase;border-radius:0}
[data-bz-node="phs-ctas"] .bz-btn--primary{background:#C41230;color:#fff;padding:18px 32px;border:0}
[data-bz-node="phs-ctas"] .bz-btn--primary:hover{background:#8f0d21;color:#fff}
[data-bz-node="phs-ctas"] .bz-btn--secondary{background:transparent;color:#fff;border:2px solid #fff;padding:16px 32px}
[data-bz-node="phs-ctas"] .bz-btn--secondary:hover{background:rgba(255,255,255,.15);border-color:#fff;color:#fff}
[data-bz-node="phs-photo"] img{width:100%;height:auto;display:block;border-radius:0}
/* The photo is a grid cell in the reference, with no block padding of its own;
   .bz-block's 16px top and bottom made the band 32px taller than the design. */
[data-bz-node="phs-media"] .bz-block,[data-bz-node="phs-media"] .bz-container{padding:0}
[data-bz-node="phs-copy"] .bz-eyebrow{line-height:normal}
[data-bz-node="phs-lead"]{margin-bottom:32px}
[data-bz-node="phs-copy"] .bz-block{padding-block:0}
